    async processLocationUpdate(deviceId, location) {
        const events = [];
        for (const fence of this.activeGeofences) {
            const isInside = fence.isPointInside(location);
            if (isInside !== this.deviceStates[deviceId]) {
                events.push({
                    type: isInside ? 'enter' : 'exit',
                    deviceId,
                    geofenceId: fence.id
                });
            }
        }
